import express, { type NextFunction, type Request, type Response } from "express";
import { z } from "zod";
import type { Db } from "./db.js";
import { ApiError } from "./errors.js";

export const MAX_ACTIVE_LOANS = 3;

const id = z.coerce.number().int().positive();
const idParams = z.object({ id });
const page = {
  limit: z.coerce.number().int().min(1).max(100).default(20),
  offset: z.coerce.number().int().min(0).default(0),
};

const bookBody = z
  .object({
    title: z.string().trim().min(1).max(300),
    author: z.string().trim().min(1).max(200),
    isbn: z
      .string()
      .trim()
      .regex(/^[0-9X-]{10,17}$/, "must be 10-17 characters: digits, X or hyphens")
      .nullish(),
  })
  .strict();

const memberBody = z
  .object({
    name: z.string().trim().min(1).max(200),
    email: z.string().trim().toLowerCase().max(254).pipe(z.email()),
  })
  .strict();

const loanBody = z.object({ bookId: id, memberId: id }).strict();

const loanQuery = z.object({
  ...page,
  memberId: id.optional(),
  bookId: id.optional(),
  status: z.enum(["active", "returned"]).optional(),
});

type Row = Record<string, any>;

const bookOut = (r: Row) => ({
  id: r.id,
  title: r.title,
  author: r.author,
  isbn: r.isbn,
  available: r.available === undefined ? undefined : r.available === 1,
  createdAt: r.created_at,
});
const memberOut = (r: Row) => ({ id: r.id, name: r.name, email: r.email, createdAt: r.created_at });
const loanOut = (r: Row) => ({
  id: r.id,
  bookId: r.book_id,
  memberId: r.member_id,
  borrowedAt: r.borrowed_at,
  returnedAt: r.returned_at,
});

function parse<T extends z.ZodType>(schema: T, data: unknown): z.output<T> {
  const result = schema.safeParse(data);
  if (!result.success) {
    throw new ApiError(
      400,
      "Validation failed",
      result.error.issues.map((i) => ({ path: i.path.join("."), message: i.message })),
    );
  }
  return result.data;
}

const isUniqueViolation = (e: unknown) =>
  e instanceof Error && /UNIQUE constraint failed/.test(e.message);

export function createApp(db: Db, now: () => Date = () => new Date()) {
  const app = express();
  app.use(express.json({ limit: "100kb" }));

  const BOOK_SELECT = `SELECT b.*, NOT EXISTS (
      SELECT 1 FROM loans l WHERE l.book_id = b.id AND l.returned_at IS NULL) AS available
    FROM books b`;

  const getBook = (bookId: number) => {
    const row = db.prepare(`${BOOK_SELECT} WHERE b.id = ?`).get(bookId);
    if (!row) throw new ApiError(404, `Book ${bookId} not found`);
    return row as Row;
  };
  const getMember = (memberId: number) => {
    const row = db.prepare("SELECT * FROM members WHERE id = ?").get(memberId);
    if (!row) throw new ApiError(404, `Member ${memberId} not found`);
    return row as Row;
  };
  const getLoan = (loanId: number) => {
    const row = db.prepare("SELECT * FROM loans WHERE id = ?").get(loanId);
    if (!row) throw new ApiError(404, `Loan ${loanId} not found`);
    return row as Row;
  };

  /** Run fn in a write transaction; roll back on any error. */
  const tx = <T>(fn: () => T): T => {
    db.exec("BEGIN IMMEDIATE");
    try {
      const out = fn();
      db.exec("COMMIT");
      return out;
    } catch (e) {
      db.exec("ROLLBACK");
      throw e;
    }
  };

  const writeCatching = <T>(what: string, fn: () => T): T => {
    try {
      return fn();
    } catch (e) {
      if (isUniqueViolation(e)) throw new ApiError(409, `${what} already exists`);
      throw e;
    }
  };

  // ---- Books ----
  app.post("/books", (req, res) => {
    const b = parse(bookBody, req.body);
    const info = writeCatching("A book with this ISBN", () =>
      db
        .prepare("INSERT INTO books (title, author, isbn) VALUES (?, ?, ?)")
        .run(b.title, b.author, b.isbn ?? null),
    );
    res.status(201).json(bookOut(getBook(Number(info.lastInsertRowid))));
  });

  app.get("/books", (req, res) => {
    const q = parse(
      z.object({ ...page, available: z.enum(["true", "false"]).optional(), q: z.string().trim().min(1).optional() }),
      req.query,
    );
    const where: string[] = [];
    const args: (string | number)[] = [];
    if (q.q) {
      where.push("(b.title LIKE ? ESCAPE '\\' OR b.author LIKE ? ESCAPE '\\')");
      const like = `%${q.q.replace(/[\\%_]/g, "\\$&")}%`;
      args.push(like, like);
    }
    if (q.available) where.push(`available = ${q.available === "true" ? 1 : 0}`);
    const sql = `SELECT * FROM (${BOOK_SELECT} ${where.length && q.q ? "" : ""}) b ${
      where.length ? "WHERE " + where.join(" AND ") : ""
    } ORDER BY b.id LIMIT ? OFFSET ?`;
    res.json(db.prepare(sql).all(...args, q.limit, q.offset).map(bookOut));
  });

  app.get("/books/:id", (req, res) => {
    res.json(bookOut(getBook(parse(idParams, req.params).id)));
  });

  app.put("/books/:id", (req, res) => {
    const { id: bookId } = parse(idParams, req.params);
    const b = parse(bookBody, req.body);
    getBook(bookId);
    writeCatching("A book with this ISBN", () =>
      db
        .prepare("UPDATE books SET title = ?, author = ?, isbn = ? WHERE id = ?")
        .run(b.title, b.author, b.isbn ?? null, bookId),
    );
    res.json(bookOut(getBook(bookId)));
  });

  app.delete("/books/:id", (req, res) => {
    const { id: bookId } = parse(idParams, req.params);
    getBook(bookId);
    const hasLoans = db.prepare("SELECT 1 FROM loans WHERE book_id = ? LIMIT 1").get(bookId);
    if (hasLoans) throw new ApiError(409, "Book has loan history and cannot be deleted");
    db.prepare("DELETE FROM books WHERE id = ?").run(bookId);
    res.status(204).end();
  });

  // ---- Members ----
  app.post("/members", (req, res) => {
    const m = parse(memberBody, req.body);
    const info = writeCatching("A member with this email", () =>
      db.prepare("INSERT INTO members (name, email) VALUES (?, ?)").run(m.name, m.email),
    );
    res.status(201).json(memberOut(getMember(Number(info.lastInsertRowid))));
  });

  app.get("/members", (req, res) => {
    const q = parse(z.object(page), req.query);
    res.json(
      db.prepare("SELECT * FROM members ORDER BY id LIMIT ? OFFSET ?").all(q.limit, q.offset).map(memberOut),
    );
  });

  app.get("/members/:id", (req, res) => {
    res.json(memberOut(getMember(parse(idParams, req.params).id)));
  });

  app.put("/members/:id", (req, res) => {
    const { id: memberId } = parse(idParams, req.params);
    const m = parse(memberBody, req.body);
    getMember(memberId);
    writeCatching("A member with this email", () =>
      db.prepare("UPDATE members SET name = ?, email = ? WHERE id = ?").run(m.name, m.email, memberId),
    );
    res.json(memberOut(getMember(memberId)));
  });

  app.delete("/members/:id", (req, res) => {
    const { id: memberId } = parse(idParams, req.params);
    getMember(memberId);
    const hasLoans = db.prepare("SELECT 1 FROM loans WHERE member_id = ? LIMIT 1").get(memberId);
    if (hasLoans) throw new ApiError(409, "Member has loan history and cannot be deleted");
    db.prepare("DELETE FROM members WHERE id = ?").run(memberId);
    res.status(204).end();
  });

  app.get("/members/:id/loans", (req, res) => {
    const { id: memberId } = parse(idParams, req.params);
    getMember(memberId);
    const q = parse(z.object({ ...page, status: z.enum(["active", "returned"]).optional() }), req.query);
    const status = q.status === "active" ? "AND returned_at IS NULL" : q.status === "returned" ? "AND returned_at IS NOT NULL" : "";
    res.json(
      db
        .prepare(`SELECT * FROM loans WHERE member_id = ? ${status} ORDER BY id LIMIT ? OFFSET ?`)
        .all(memberId, q.limit, q.offset)
        .map(loanOut),
    );
  });

  // ---- Loans ----
  app.post("/loans", (req, res) => {
    const { bookId, memberId } = parse(loanBody, req.body);
    const loan = tx(() => {
      getBook(bookId);
      getMember(memberId);
      const { n } = db
        .prepare("SELECT COUNT(*) AS n FROM loans WHERE member_id = ? AND returned_at IS NULL")
        .get(memberId) as { n: number };
      if (n >= MAX_ACTIVE_LOANS) {
        throw new ApiError(409, `Member already has ${MAX_ACTIVE_LOANS} books on loan`);
      }
      const info = writeCatching("An active loan for this book", () =>
        db
          .prepare("INSERT INTO loans (book_id, member_id, borrowed_at) VALUES (?, ?, ?)")
          .run(bookId, memberId, now().toISOString()),
      );
      return getLoan(Number(info.lastInsertRowid));
    });
    res.status(201).json(loanOut(loan));
  });

  app.get("/loans", (req, res) => {
    const q = parse(loanQuery, req.query);
    const where: string[] = [];
    const args: number[] = [];
    if (q.memberId) (where.push("member_id = ?"), args.push(q.memberId));
    if (q.bookId) (where.push("book_id = ?"), args.push(q.bookId));
    if (q.status === "active") where.push("returned_at IS NULL");
    if (q.status === "returned") where.push("returned_at IS NOT NULL");
    const sql = `SELECT * FROM loans ${where.length ? "WHERE " + where.join(" AND ") : ""} ORDER BY id LIMIT ? OFFSET ?`;
    res.json(db.prepare(sql).all(...args, q.limit, q.offset).map(loanOut));
  });

  app.get("/loans/:id", (req, res) => {
    res.json(loanOut(getLoan(parse(idParams, req.params).id)));
  });

  app.post("/loans/:id/return", (req, res) => {
    const { id: loanId } = parse(idParams, req.params);
    const loan = tx(() => {
      const existing = getLoan(loanId);
      if (existing.returned_at) throw new ApiError(409, "Loan was already returned");
      db.prepare("UPDATE loans SET returned_at = ? WHERE id = ?").run(now().toISOString(), loanId);
      return getLoan(loanId);
    });
    res.json(loanOut(loan));
  });

  // ---- Errors ----
  app.use((_req, _res, next) => next(new ApiError(404, "Route not found")));
  app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
    if (err instanceof ApiError) {
      res.status(err.status).json({ error: err.message, details: err.details });
    } else if (err?.type === "entity.parse.failed") {
      res.status(400).json({ error: "Malformed JSON body" });
    } else if (err?.type === "entity.too.large") {
      res.status(413).json({ error: "Request body too large" });
    } else {
      console.error(err);
      res.status(500).json({ error: "Internal server error" });
    }
  });

  return app;
}
EOF
